styles:
  :root { color-scheme: dark; }
  body {
    background: #020617; color: #f1f5f9;
    font-family: Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  }
  code, kbd, .mono { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }
  .surface { background: rgba(15,23,42,.6); }
  .surface-sunken { background: rgba(2,6,23,.5); }

  /* Hero band only. Deeper than the detail route's because this is the page's
     ground rather than a strip above content. */
  .hero-band {
    background:
      radial-gradient(1200px 520px at 18% -14%, rgba(56,189,248,.13), transparent 60%),
      radial-gradient(900px 440px at 84% -8%, rgba(217,70,239,.10), transparent 58%),
      linear-gradient(180deg, rgba(30,41,59,.6) 0%, rgba(2,6,23,0) 82%);
  }
  .hero-band::after {
    content: ""; position: absolute; inset: 0; pointer-events: none;
    background-image:
      linear-gradient(to right, rgba(148,163,184,.085) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(148,163,184,.085) 1px, transparent 1px);
    background-size: 56px 56px;
    -webkit-mask-image: linear-gradient(180deg, #000 0%, transparent 80%);
    mask-image: linear-gradient(180deg, #000 0%, transparent 80%);
  }
  :focus-visible { outline: 2px solid #38bdf8; outline-offset: 2px; border-radius: 6px; }
  @media (prefers-reduced-motion: reduce) { * { transition: none !important; } }


/* Composition diagram only. The four role columns remain unboxed. */
.composition-demo {
  background: radial-gradient(ellipse 85% 80% at 50% 102%, rgba(245,158,11,.065), transparent 72%);
}
.compose-node { position: relative; min-width: 0; text-align: center; transition: transform .22s ease; }
.compose-node:hover { transform: translateY(-3px); }
.compose-node-icon {
  display: grid; place-items: center; width: 34px; height: 34px;
  margin: 0 auto 6px; padding: 4px; border-radius: 10px;
  background: rgba(15,23,42,.82); border: 1px solid rgba(100,116,139,.36);
  transition: border-color .22s ease, box-shadow .22s ease;
}
.compose-node:hover .compose-node-icon {
  border-color: var(--compose-tone); box-shadow: 0 0 22px -7px var(--compose-tone);
}
.compose-node-icon [data-mark] { display: block; width: 100%; height: 100%; }
.compose-link-svg { width: 100%; height: 33px; display: block; overflow: visible; }
.compose-link-svg path { fill: none; stroke: rgba(148,163,184,.29); stroke-width: 1.6; vector-effect: non-scaling-stroke; }
.compose-link-svg .compose-join { stroke: rgba(251,191,36,.65); }
.compose-result {
  display: inline-flex; align-items: center; gap: 9px; padding: 7px 12px;
  border-radius: 12px; border: 1px solid rgba(251,191,36,.27);
  background: linear-gradient(100deg, rgba(251,191,36,.085), rgba(15,23,42,.82));
  box-shadow: 0 4px 22px rgba(2,6,23,.2);
}
.compose-result-mark { height: 30px; width: 30px; padding: 2px; overflow: hidden;
  border-radius: 8px; background: rgba(2,6,23,.85); }
/* The Agent mark is generated by the inline mock renderer at runtime. */
.compose-result-mark > div { display: grid; grid-template-columns: repeat(2,minmax(0,1fr));
  grid-template-rows: repeat(2,minmax(0,1fr)); gap: 2px; width: 100%; height: 100%; }
.compose-result-mark > div > div { min-width: 0; min-height: 0; border-radius: 3px; }

@media (max-width: 767px) {
  .compose-node-icon { width: 30px; height: 30px; padding: 4px; }
}
@media (prefers-reduced-motion: no-preference) {
  .composition-demo.is-revealed .compose-node {
    animation: compose-appear .65s cubic-bezier(.2,.85,.25,1) both;
    animation-delay: calc(var(--compose-order) * 85ms);
  }
  .composition-demo.is-revealed .compose-join {
    stroke-dasharray: 1200; stroke-dashoffset: 1200;
    animation: compose-trace .95s .45s ease-out forwards;
  }
  .composition-demo.is-revealed .compose-result {
    animation: compose-appear .7s .98s cubic-bezier(.2,.85,.25,1) both;
  }
  @keyframes compose-appear {
    from { opacity: .22; transform: translateY(10px) scale(.965); }
    to   { opacity: 1; transform: translateY(0) scale(1); }
  }
  @keyframes compose-trace { to { stroke-dashoffset: 0; } }
}

:root { color-scheme: dark; }
body {
  background: #020617; color: #f1f5f9;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
}
code, kbd, .mono { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }
/* Panel RAISED = bg-slate-900 at 50% (BASE_TRANSPARENCY 40 + RAISED 10). */
.panel-raised { background: rgba(15,23,42,.5); }
.line-clamp-2 {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
/* Description clamp. Measured against the real 20 results: at the desktop
   row width (~130 ch/line) two lines show 20/20 descriptions in full and
   only 5 rows need the second line. At mobile width (~46 ch/line) one line
   shows only 2/20, so the clamp opens to three there (18/20 in full). */
.desc {
  display: -webkit-box; -webkit-box-orient: vertical; overflow: hidden;
  -webkit-line-clamp: 3;
}
@media (min-width: 640px) { .desc { -webkit-line-clamp: 2; } }

/* Neutralized kind identity geometry for category navigation (not package marks).
   Don't assign name-seeded gradients to artifact *types*. Production should
   reuse the existing ToolBox shapes, with a muted mono palette. */
.category-mark { color: #94a3b8; }
.category-link[aria-pressed="true"] { border-color: rgba(56,189,248,.50); background: rgba(14,165,233,.08); }
.category-link:hover .category-mark { color: #e2e8f0; }
[hidden] { display: none !important; }
@media (max-width: 1023px) { #filter-options:not(.filters-expanded) { display:none; } }
summary::-webkit-details-marker { display: none; }
:focus-visible { outline: 2px solid #38bdf8; outline-offset: 2px; border-radius: 6px; }
