  /* ── Production ground. The site is dark-committed; paint it explicitly. ── */
  :root { color-scheme: dark; --global-header-height: 64px; --compact-package-height: 0px; }
  body {
    background: #020617;                 /* slate-950 */
    color: #f1f5f9;                      /* slate-100 */
    font-family: Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  }
  code, kbd, .mono { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }

  /* ── Hero-band texture. Scoped to the hero only (tasks.md M8B.1).
        On a dark ground this is how layering reads without drop shadows. ── */
  .hero-band {
    background:
      radial-gradient(1100px 420px at 12% -18%, rgba(56,189,248,.10), transparent 62%),
      radial-gradient(820px 380px at 88% -12%, rgba(168,85,247,.09), transparent 58%),
      linear-gradient(180deg, rgba(30,41,59,.55) 0%, rgba(2,6,23,0) 78%);
  }
  .hero-band::after {                    /* faint grid, keeps the band from reading flat */
    content: ""; position: absolute; inset: 0; pointer-events: none;
    background-image:
      linear-gradient(to right, rgba(148,163,184,.075) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(148,163,184,.075) 1px, transparent 1px);
    background-size: 56px 56px;
    -webkit-mask-image: linear-gradient(180deg, #000 0%, transparent 85%);
    mask-image: linear-gradient(180deg, #000 0%, transparent 85%);
  }

  .surface { background: rgba(15,23,42,.6); }        /* slate-900/60 */
  .surface-sunken { background: rgba(2,6,23,.5); }   /* slate-950/50 */

  /* Dashed connector for transitive edges */
  .edge, .edge-dashed { background: #334155; }
  .edge-dashed {
    background: repeating-linear-gradient(to bottom, #334155 0 4px, transparent 4px 8px);
  }

  /* Two independent sticky triggers: the title row controls this compact
     identity strip; the package tabs dock later, immediately beneath it.
     Use the real global header height, including its mobile search row. */
  .compact-package-context {
    position: fixed;
    top: var(--global-header-height);
    left: 0;
    right: 0;
    z-index: 35; /* Below global header, above the tab bar. */
    height: 54px;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transform: translateY(-6px);
    background: rgba(15, 23, 42, .97);
    border-bottom: 1px solid rgba(51,65,85,.7);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    transition: opacity .18s ease, transform .18s ease, visibility .18s ease;
  }
  .compact-package-context.is-visible {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
    transform: translateY(0);
  }
  .package-dock {
    position: sticky;
    top: calc(var(--global-header-height) + var(--compact-package-height));
    z-index: 30;
    background: rgba(2, 6, 23, .96);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    box-shadow: 0 4px 18px rgba(2, 6, 23, .25);
  }
  .package-tabs { background: rgba(2,6,23,.72); }
  .phase-node { scroll-margin-top: calc(var(--global-header-height) + 132px); }
  #package-top { scroll-margin-top: var(--global-header-height); }
  .phase-node:target {
    border-color: rgba(163, 230, 53, .65);
    box-shadow: 0 0 0 1px rgba(163, 230, 53, .19), 0 0 28px rgba(163, 230, 53, .035);
  }
  #identity-avatar > div, #identity-avatar-sm > div, #identity-avatar-sticky > div { width:100%; height:100%; display:grid; grid-template-columns: repeat(2, minmax(0, 1fr)); grid-template-rows:repeat(2,minmax(0,1fr)); gap:2px; }
  #identity-avatar > div > div, #identity-avatar-sm > div > div, #identity-avatar-sticky > div > div { min-height:0; min-width:0; border-radius:4px; }
  .route-link { text-decoration: none; }
  .route-link:hover { color: #bef264; text-decoration: underline; }
  .route-row { display: grid; grid-template-columns: minmax(0,1fr) 18px minmax(0,1fr); gap: 8px; align-items: center; }
  @media (max-width: 520px) { .route-row { grid-template-columns: minmax(0,1fr) 14px minmax(0,1fr); gap: 5px; } }

  :focus-visible { outline: 2px solid #38bdf8; outline-offset: 2px; border-radius: 6px; }

  /* Capability chips: only one dropdown open at a time across the panel. */
  .chev { transition: transform .15s ease; }
  [aria-expanded="true"] .chev { transform: rotate(180deg); }
  .cap[aria-expanded="true"] { box-shadow: inset 0 0 0 1px currentColor; }

  @media (prefers-reduced-motion: reduce) { * { transition: none !important; animation: none !important; } }

  /* Preview-only Health tab: retains the main page's sticky identity and tabs.
     In production reuse the existing tab router/components, not this script. */
  [data-preview-panel][hidden] { display: none !important; }
  .health-detail-tab { min-height: 680px; }
  /* Keep scope outcomes scannable even when a mock-specific utility is absent. */
  .health-detail-tab .apds-scope-row { display:grid; grid-template-columns:minmax(0,1fr) auto; align-items:center; gap:12px; }
  @media(max-width:520px) { .health-detail-tab .apds-scope-row { grid-template-columns:minmax(0,1fr); gap:4px; } }

  .health-detail-tab > header { margin-bottom: 2rem; }
  .health-detail-tab .chev { display:inline-block; transition: transform .15s ease; }
  .health-detail-tab [aria-expanded="true"] .chev { transform: rotate(180deg); }
  .health-detail-tab details[open] > summary .chev { transform:rotate(180deg); }
  .health-detail-tab details summary::-webkit-details-marker { display:none; }
  .health-detail-tab details summary { list-style:none; }
  .health-detail-tab details summary::marker { display:none; }

/* Bindings inspector: plain sections, fine dividers, expandable authored rows.
   Keep native <details> keyboard-accessible; no independent accordion state. */
.bindings-detail-tab .binding-phase summary,
.bindings-detail-tab .binding-source summary { list-style:none; }
.bindings-detail-tab .binding-phase summary::-webkit-details-marker,
.bindings-detail-tab .binding-source summary::-webkit-details-marker { display:none; }
.bindings-detail-tab .binding-chevron { transition:transform .16s ease; }
.bindings-detail-tab details[open] > summary .binding-chevron { transform:rotate(180deg); }
.bindings-detail-tab .binding-phase-summary:focus-visible,
.bindings-detail-tab .binding-source summary:focus-visible {outline:2px solid #38bdf8;outline-offset:3px;}
.bindings-detail-tab .binding-field-row:last-child {border-bottom:0;}
@media (prefers-reduced-motion: reduce) {.bindings-detail-tab .binding-chevron {transition:none!important;}}

